{"question": "Xử trí chấn thương hàm mặt trễ thì thế nào?", "claim": "Xử trí chấn thương phần mềm vùng hàm mặt trễ hạn nhưng tiên lượng vẫn đảm bảo kết quả tốt.", "internal_evidence": [{"evidence_id": "I1", "content": "Bản nháp ghi nhận tiến hành xử trí chấn thương phần mềm vùng hàm mặt trễ hạn nhưng tiên lượng vẫn đảm bảo kết quả tốt."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "- Điều trị sớm và đúng nguyên tắc sẽ cho kết quả tốt."}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "1.Tiên lượng Nếu dẫn lưu mủ phối hợp với điều trị răng nguyên nhân thì có kết quả điều trị tốt."}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "- Cắn hở do răng: nếu điều trị đúng phác đồ trên thì sẽ có kết quả tốt. Nếu không điều trị kịp thời thì có thể chuyển thể thành cắn hở do xương và điều trị phức tạp hơn."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "- Bước 3: Đánh giá đáp ứng với điều trị pha 1 Hẹn bệnh nhân đến khám lại và đánh giá kết quả sau điều trị các yếu tố bệnh căn. Cần kiểm tra lại các tình trạng dưới đây:"}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["53. CHẤN THƯƠNG PHẦN MỀM VÙNG HÀM MẶT", "V. TIÊN LƯỢ NG VÀ BIẾN CHỨNG", "1. Tiên lượng"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["32. ÁP XE VÙNG SÀN MIỆNG", "V. TIÊN LƯỢNG VÀ BIẾN CHỨNG"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["20 . KHỚP CẮN HỞ", "V. TIÊN LƯỢNG VÀ BIẾN CHỨNG", "1. Tiên lượng"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["7. VIÊM QUANH RĂNG TIẾN TRIỂN CHẬM", "IV. ĐIỀU TRỊ", "2. Phác đồ điều trị"]}], "conversation": [{"role": "user", "content": "Xử trí chấn thương hàm mặt trễ thì thế nào?"}, {"role": "assistant", "content": "Trễ hạn chắc chắn để lại di chứng nặng nề rồi."}]}
