Tham et al. | Yes | NA | Yes | No | Yes | Yes | Yes | Yes | Yes"}], "public_sources": [{"evidence_id": "P1", "title": "The Effectiveness of Topical Fluorides in Preventing Dental Caries in Children and Adolescents: A Systematic Review and Meta-Analysis", "heading_path": ["Body", "Discussion"]}, {"evidence_id": "P2", "title": "Clinical and Microbiological Effects of Streptococcus salivarius K12 Lozenges and Zinc Mouthrinse on Persistent Intra-Oral Halitosis", "heading_path": ["Body", "3. Results"]}, {"evidence_id": "P3", "title": "Clinical and Microbiological Changes Following Multi-Strain Probiotic Mouthrinse Use in Dental Students with Halitosis: A Prospective Single-Arm Study", "heading_path": ["Body", "Microbiological Analysis", "Statistical Analysis"]}, {"evidence_id": "P4", "title": "Traumatic Dental Injuries’ Prevalence across Diverse Healthcare Settings: A Systematic Review and Meta-Analysis", "heading_path": ["Body", "3. Results:"]}]}
