{"question": "Khoảng tích dịch trong buông khớp thái dương hàm khi há miệng tối đa là bao nhiêu và vị trí chính xác của lồi cầu là gì?", "claim": "Buông khớp dưới chứa khoảng 0,9 ml dịch khớp và khi miệng há tối đa, lồi cầu thường ở dưới và ngay trước chỗ lồi nhất của lồi khớp.", "internal_evidence": [{"evidence_id": "I1", "content": "Khoảng tích dịch trong buông khớp thái dương hàm khi há miệng tối đa là 2,5 ml. Tại thời điểm này, lồi cầu xương hàm dưới không nằm ở vị trí dưới hay trước lồi khớp mà di chuyển hoàn toàn ra phía sau, tiếp xúc trực tiếp với thành sau của hố khớp."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "Là ung thư biểu mô phát sinh ở vùng niêm mạc, thường ở phần trước của vùng sàn miệng giữa mặt trong cung răng và mặt dưới lưỡi. Ung thư sàn miệng phát triển nhanh và xâm lấn vào mô xung quanh."}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "Dính khớp thái dương hàm là tình trạng hạn chế hoặc mất vận động của khớp do sự xơ hóa, vôi hóa các thành phần của khớp như lồi cầu, ổ chảo, hõm khớp, dây chằng ngoài bao khớp."}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "+ Đau khi ấn dọc từ gai mũi trước đến lồi củ xương hàm trên."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "- Nhổ răng: trong trường hợp cần khoảng để dịch chuyển về khớp cắn loại I thì thường phải nhổ răng hàm nhỏ thứ nhất hàm trên và răng hàm nhỏ thứ hai hàm dưới."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["50. UNG THƯ SÀN MIỆNG", "I. ĐỊNH NGHĨA"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["57. DÍNH KHỚP THÁI DƯƠNG HÀM", "I. ĐỊNH NGHĨA"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["55. GÃY XƯƠNG HÀM TRÊN", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.2. Gãy toàn bộ", "b. Gãy ngang"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["17. SAI KHỚP CẮN LOẠI II TIỂU LOẠI I DO RĂNG", "IV. ĐIỀU TRỊ", "2. Điều trị cụ thể"]}]}
