{"question": "Dấu hiệu lâm sàng chính để chẩn đoán xác định gãy ngang xương hàm trên toàn bộ là gì?", "claim": "Khi khám lâm sàng trường hợp gãy toàn bộ xương hàm trên dạng gãy ngang, bác sĩ sẽ phát hiện thấy hiện tượng di động xương hàm trên.", "internal_evidence": [{"evidence_id": "I1", "content": "- Khi thực hiện khám lâm sàng trường hợp chấn thương vùng mặt có gãy toàn bộ xương hàm trên dạng gãy ngang, bác sĩ cần kiểm tra kỹ độ vững chắc.\n- Dấu hiệu đặc trưng và quan trọng nhất giúp xác định tổn thương là phát hiện thấy hiện tượng di động bất thường của toàn bộ khối xương hàm trên khi lay nhẹ."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "Chẩn đoán xác định dựa vào các triệu chứng lâm sàng, cận lâm sàng và tính chất dịch tễ."}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "T | N | M\nT0: Khối u không xác định được trên lâm sàng | N0: Không có hạch | M0: Chưa có di căn xa"}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "+ Di động xương hàm trên khi khám."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "- Thể lâm sàng hiếm gặp là nang nhái ở cổ, xảy ra khi nang xuyên qua cơ hàm móng và biểu hiện thành khối phồng ở vùng cổ."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["43. VIÊM TUYẾ N NƯỚ C BỌ T MANG TAI MẠ N TÍ NH", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["49. UNG THƯ LƯỠI", "III. CHẨN ĐOÁN", "2. Chẩn đoán giai đoạn: Sử dụng hệ thống TNM."]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["55. GÃY XƯƠNG HÀM TRÊN", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.2. Gãy toàn bộ", "b. Gãy ngang"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["26. NANG NHÁI SÀN MIỆNG", "III. CHẨN ĐOÁN", 