{"question": "Triệu chứng lâm sàng tại chỗ khi mủ tụ ở sau vùng trâm trong áp xe thành bên họng là gì?", "claim": "Khi mủ tụ ở sau vùng trâm trong áp xe thành bên họng, bệnh nhân thường bị khít hàm nặng và sưng to rất rõ ở bên ngoài mặt.", "internal_evidence": [{"evidence_id": "I1", "content": "Khi mủ tụ ở sau vùng trâm trong áp xe thành bên họng, triệu chứng lâm sàng chủ yếu là sưng nề vùng họng và khó nuốt, trong khi tình trạng khít hàm thường không xuất hiện hoặc chỉ ở mức độ rất nhẹ, và vùng mặt bên ngoài thường không có biểu hiện sưng to rõ rệt."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "Là ung thư biểu mô phát sinh ở vùng niêm mạc, thường ở phần trước của vùng sàn miệng giữa mặt trong cung răng và mặt dưới lưỡi. Ung thư sàn miệng phát triển nhanh và xâm lấn vào mô xung quanh."}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "+ Nếu mủ tụ ở vùng trước trâm thì thấy sưng đau dọc cơ ức đòn chũm.Khởi đầu vùng dưới hàm ,góc hàm có 1 khối sưng lớn, da trên khối sưng nóng đỏ hoặc tím, căng, nề, có thể thâm nhiễm lan rộng lên vùng mang tai.Lồi bờ nền xương hàm dưới bị xóa."}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "+ Sưng nền phần trước thành bên hầu, đẩy amidan và vòm miệng vào giữa. Do thành bên hầu bị sưng nề nên bệnh nhân thường có khó thở."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "+ Nếu mủ tụ ở sau vùng trâm: bệnh cảnh lâm sàng tương tự như nhiễm khuẩn máu. Bệnh nhân ít khi bị khít hàm, sưng bên ngoài cũng ít hơn so với áp xe ở trước trâm. Trong miệng thây sưng thành bên hầu."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["50. UNG THƯ SÀN MIỆNG", "I. ĐỊNH NGHĨA"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["34. ÁP XE THÀNH BÊN HỌNG", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1. Lâm sàng", "b. Tại chỗ"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["34. ÁP XE THÀNH BÊN HỌNG", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1. Lâm sàng", "b. Tại chỗ"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["34. ÁP XE THÀNH BÊN HỌNG", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1. Lâm sàng", "b. Tại chỗ"]}]}
