{"question": "Quy trình xử trí khi răng bị bật ra khỏi ổ răng bao gồm những bước nào để đảm bảo ổn định?", "claim": "Cách đặt răng vào chỗ cũ và nẹp răng bị bật ra khỏi ổ răng giúp ổn định răng vững chắc ở trạng thái di động nhưng không di lệch.", "internal_evidence": [{"evidence_id": "I1", "content": "- Các bước xử trí khi răng bị bật ra khỏi ổ răng\n- Thực hiện đặt lại răng vào đúng vị trí ban đầu trên cung hàm\n- Tiến hành nẹp cố định để giữ răng ổn định ở trạng thái vững chắc nhưng không bị di lệch"}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "Ổn định răng vững chắc (di động nhưng không di lệch)"}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "Gãy răng làm lộ ngà nhưng không lộ tủy có thể được xử lý bằng cách hàn răng hoặc làm chụp."}, {"quote_id": "P2.Q2", "evidence_id": "P2", "text": "Gãy răng có lộ tủy thì thường yêu cầu điều trị tủy."}, {"quote_id": "P2.Q3", "evidence_id": "P2", "text": "Không được đặt lại răng sữa bị bật ra khỏi ổ răng trở lại chỗ cũ."}, {"quote_id": "P2.Q4", "evidence_id": "P2", "text": "Răng vĩnh viễn bị bật ra khỏi ổ răng cần phải được đặt lại vào ổ răng ngay lập tức (nếu có thể); hoặc được rửa nhẹ nhàng (nhưng không chà mạnh) trong khoảng ≤ 10 giây và ngâm trong nước muối, sữa, khăn ướt, hoặc miệng của bệnh nhân, chuyển đến nha sĩ để đặt răng vào huyệt ổ răng càng sớm càng tốt."}, {"quote_id": "P2.Q5", "evidence_id": "P2", "text": "Răng bị bật ra khỏi ổ răng và được đặt trở lại chỗ cũ nhanh chóng thường có thể sử dụng được nhưng cuối cùng rất có thể sẽ phải điều trị tủy."}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "Giữ răng bằng mão răng, nhẹ nhàng đưa nó vào ổ răng theo hướng giải phẫu chính xác (sử dụng phía đối diện như một hướng dẫn nếu cần)."}, {"quote_id": "P3.Q2", "evidence_id": "P3", "text": "Nhẹ nhàng đẩy răng vào ổ răng (ấn vào thân răng) để giữ răng nhưng không đè ép bất kỳ mô nào ở chân răng. Chỉ sử dụng ngón tay đè vào."}, {"quote_id": "P3.Q3", "evidence_id": "P3", "text": "Kiểm tra khớp cắn: Cho bệnh nhân cắn nhẹ nhàng và từ từ cắn xuống để chắc chắn rằng răng của đối phương không bị xê dịch. Điều chỉnh lại vị trí của răng nếu cần để bệnh nhân có thể mang lại răng bình thường."}, {"quote_id": "P3.Q4", "evidence_id": "P3", "text": "Nẹp răng (xem bên dưới)."}, {"quote_id": "P3.Q5", "evidence_id": "P3", "text": "Nếu răng không thể ngồi an toàn hoặc định hướng một cách chắc chắn, hãy gửi bệnh nhân trực tiếp đến nha sĩ."}], "public_sources": [{"evidence_id": "P1", "title": "Cách đặt răng vào chỗ cũ và nẹp răng bị bật ra khỏi ổ răng", "heading_path": ["Mô tả từng bước về việc đặt răng vào chỗ cũ và nẹp răng bị bật ra khỏi ổ răng"]}, {"evidence_id": "P2", "title": "Răng bị gãy và bị bật ra khỏi ổ răng", "heading_path": ["Những điểm chính"]}, {"evidence_id": "P3", "title": "Cách đặt răng vào chỗ cũ và nẹp răng bị bật ra khỏi ổ răng", "heading_path": ["Mô tả từng bước về việc đặt răng vào chỗ cũ và nẹp răng bị bật ra khỏi ổ răng"]}]}
