{"question": "Phương pháp phá hủy thần kinh ngoại vi trong điều trị đau dây thần kinh V bằng cách tiêm Alcohol áp dụng cho những vị trí nào và với liều lượng bao nhiêu?", "claim": "Khi thực hiện phương pháp phá hủy thần kinh ngoại vi bằng tiêm Alcohol để điều trị đau dây thần kinh V, bác sĩ cần tiêm tại các vị trí lỗ cằm, lỗ dưới ổ mắt, gai Spix, bờ trên ổ mắt với loại Alcohol 100%, gây tê trước và lượng tiêm khoảng 1ml.", "internal_evidence": [{"evidence_id": "I1", "content": "Khi thực hiện phương pháp phá hủy thần kinh ngoại vi nhằm kiểm soát cơn đau dây thần kinh V kháng trị, bác sĩ cần tiến hành gây tê vùng trước, sau đó tiêm dung dịch Alcohol 100% với liều lượng khoảng 1ml tại các mốc giải phẫu quan trọng gồm lỗ cằm, lỗ dưới ổ mắt, gai Spix và bờ trên ổ mắt."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "+ Tiêm Alcohol vào các vị trí: lỗ cằm, lỗ dưới ổ mắt, gai Spix, bờ trên ổ mắt: sử dụng Alcohol loại 100%, gây tê trước khi tiêm lượng Alcohol khoảng 1ml."}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "- Phẫu thuật chỉnh hình xương hàm dưới: áp dụng trong các trường hợp nặng không thể điều trị bù trừ bằng nắn chỉnh răng đơn thuần."}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "- Cần khám, phát hiện và điều trị sớm để loại bỏ các thói quen xấu gây ra sai khớp cắn loại II tiểu loại I do răng."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "- Nhổ răng: trong trường hợp cần khoảng để dịch chuyển về khớp cắn loại I thì thường phải nhổ răng hàm nhỏ thứ nhất hàm trên và răng hàm nhỏ thứ hai hàm dưới."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["48. ĐAU DÂY THẦN KINH V", "IV. ĐIỀU TRỊ", "2. Điều trị cụ thể", "2.2. Điều trị triệu chứng", "2.2.2 Ngoại khoa", "b. Phương pháp phá hủy thần kinh ngoại vi"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["15. SAI KHỚP CẮN LOẠI II DO KÉM PHÁT TRIỂN XƯƠNG HÀM DƯỚI", "IV. ĐIỀU TRỊ", "2. Điều trị cụ thể", "2.2. Bệnh nhân đã hết thời kỳ tăng trưởng"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["17. SAI KHỚP CẮN LOẠI II TIỂU LOẠI I DO RĂNG", "VI. PHÒNG BỆNH"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["17. SAI KHỚP CẮN LOẠI II TIỂU LOẠI I DO RĂNG", "IV. ĐIỀU TRỊ", "2. Điều trị cụ thể"]}]}
