{"question": "Viêm tấy lan tỏa vùng hàm mặt có cần thực hiện chẩn đoán phân biệt không?", "claim": "Bệnh nhân bị viêm tấy lan tỏa vùng hàm mặt cần phải tiến hành các xét nghiệm phức tạp để chẩn đoán phân biệt với các bệnh lý u xương hàm.", "internal_evidence": [{"evidence_id": "I1", "content": "Quá trình thăm khám vùng hàm mặt tập trung phân tích kỹ lưỡng các mốc giải phẫu quan trọng của xương hàm dưới bao gồm vùng góc hàm, ngành lên cùng với hướng mọc trục của các răng cối lớn trong vòm miệng."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "Nang tuyến nước bọt dưới hàm và dưới lưỡi có các dấu hiệu lâm sàng khá điển hình và không cần chẩn đoán phân biệt."}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "Viêm tấy tỏa lan vùng hàm mặt có các biểu hiện lâm sàng rõ và tiến triển nhanh, không cần chẩn đoán phân biệt."}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "Viêm tủy có hồi phục chẩn đoán phân biệt với sâu ngà sâu và viêm tủy không hồi phục: Dựa vào các dấu hiệu lâm sàng và cận lâm sàng."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "Tình trạng cắn chéo luôn có các triệu chứng lâm sàng và cận lâm sàng rõ rệt, vì vậy không cần chẩn đoán phân biệt với các rối loạn khớp cắn khác."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["27. NANG TUYẾN NƯỚC BỌT DƯỚI HÀM VÀ DƯỚI LƯỠI", "III. CHẨN ĐOÁN", "2. Chẩn đoán phân biệt"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["35. VIÊM TẤY LAN TỎA VÙNG HÀM MẶT", "III. CHẨN ĐOÁN", "2. Chẩn đoán phân biệt"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["11. VIÊM TỦY RĂNG", "III. CHẨN ĐOÁN", "1. Viêm tủy có hồi phục", "1.2. Chẩn đoán phân biệt"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["21. CẮN CHÉO", "III. CHẨN ĐOÁN", "3. Chẩn đoán phân biệt"]}]}
