{"question": "Triệu chứng lâm sàng tại chỗ của áp xe thành bên họng trong giai đoạn đầu và giai đoạn sau như thế nào?", "claim": "Ở giai đoạn đầu của áp xe thành bên họng, khối sưng có mật độ cứng và bệnh nhân đau dữ dội khi sờ vào, sau đó khối sẽ mềm dần, ấn lõm hoặc có dấu hiệu chuyển sóng.", "internal_evidence": [{"evidence_id": "I1", "content": "Trong quá trình tiến triển của bệnh lý áp xe thành bên họng, biểu hiện lâm sàng tại chỗ thay đổi rõ rệt qua từng giai đoạn. Ở giai đoạn đầu, khi thăm khám sờ nắn sẽ thấy khối sưng có mật độ cứng chắc và bệnh nhân cảm thấy đau đớn dữ dội. Sang giai đoạn sau, tổn thương tiến triển thành ổ mủ, khối sưng trở nên mềm dần, khi ấn có cảm giác lõm hoặc xuất hiện dấu hiệu chuyển sóng."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "Triệu chứng | Sâu răng sữa giai đoạn sớm | Thay đổi màu sắc răng không do sâu\nVị trí | Hố rãnh mặt nhai, mặt gần, xa, mặt ngoài hoặc mặt trong các răng hàm sữa. Mặt gần, xa, mặt ngoài hoặc mặt trong các răng cửa và răng nanh sữa. | Toàn bộ mặt răng, có thể ở một răng do bị chấn thương gây chết tủy, hoặc trên nhiều răng do thiểu sản men răng sữa, có tính chất đối xứng."}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "+ Giai đoạn đầu khối có mật độ cứng, về sau ấn lõm hoặc có dấu hiệu chuyển sóng. Bệnh nhân đau dữ dội khi sờ vào."}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "Dựa vào triệu chứng lâm sàng và cận lâm sàng. Có thể gặp cắn chéo phía trước hoặc cắn chéo phía sau hoặc phối hợp."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "- Triệu chứng cơ năng Đau: bệnh nhân có cảm giác đau tự nhiên, nhẹ thoáng qua, cơn đau ngắn. Khi ăn các chất kích thích nóng, lạnh, chua, ngọt… thì có cảm giác đau hoặc ê buốt tăng lên và sớm hết đau khi ngừng chất kích thích."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["4. SÂU RĂNG SỮA", "III. CHẨN ĐOÁN", "3. Chẩn đoán phân biệt", "a. Các tổn thương sâu răng sớm chẩn đoán phân biệt với thay đổi màu sắc răng"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["34. ÁP XE THÀNH BÊN HỌNG", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1. Lâm sàng", "b. Tại chỗ"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["21. CẮN CHÉO", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["5. VIÊM TỦY RĂNG SỮA", "III. CHẨN ĐOÁN", "1. Viêm tủy răng sữa có hồi phục", "a. Lâm sàng"]}]}
