{"question": "Quy trình điều trị viêm tủy răng có hồi phục bao gồm bước hàn phục hồi xoang hàn như thế nào?", "claim": "Trong điều trị viêm tủy có hồi phục, một trong các bước chuyên môn cần thực hiện là hàn phục hồi xoang hàn.", "internal_evidence": [{"evidence_id": "I1", "content": "Trong nhóm bệnh nhân cần điều trị viêm tủy có hồi phục, việc tiến hành hàn phục hồi xoang hàn được áp dụng như một kỹ thuật thiết yếu nhằm bít kín ngà răng bộc lộ, ngăn chặn vi khuẩn xâm nhập và bảo vệ mô tủy sống bên trong khỏi các kích thích cơ học cũng như nhiệt độ."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "- Các tổn thương sâu răng sớm: nếu thực hiện tốt việc tăng cường quá trình tái khoáng thì các tổn thương có thể tự phục hồi."}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "Viêm tủy có hồi phục là tình trạng viêm mô tủy nhưng có khả năng hồi phục khi loại bỏ được các yếu tố bệnh nguyên."}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "Triệu chứng | Viêm tủy không hồi phục | Viêm tủy có hồi phục | Viêm quanh cuống cấp\nĐau, ê buốt khi ăn các chất kích thích như nóng, lạnh, chua, ngọt… | Đau tăng khi có kích thích, hết kích thích đau còn kéo dài. | Có đau nhưng sau khi hết kích thích thì còn đau buốt nhẹ hoặc hết đau ngay. | Không đau."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "- Hàn phục hồi xoang hàn:"}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["4. SÂU RĂNG SỮA", "V. TIÊN LƯỢNG VÀ BIẾN CHỨNG", "1. Tiên lượng"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["5. VIÊM TỦY RĂNG SỮA", "III. CHẨN ĐOÁN", "1. Viêm tủy răng sữa có hồi phục"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["5. VIÊM TỦY RĂNG SỮA", "III. CHẨN ĐOÁN", "2. Viêm tủy răng sữa không hồi phục", "c. Chẩn đoán phân biệt"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["11. VIÊM TỦY RĂNG", "IV. ĐIỀU TRỊ", "1. Viêm tủy có hồi phục"]}]}
