{"question": "Hệ thống TNM phân loại giai đoạn ung thư lưỡi với các chỉ số T1, N1, M1 được quy định như thế nào?", "claim": "Trong hệ thống TNM chẩn đoán giai đoạn ung thư lưỡi, T1 là khối u có đường kính dưới 2cm, N1 xác định được hạch đơn cùng bên dưới 3cm và M1 có biểu hiện di căn xa.", "internal_evidence": [{"evidence_id": "I1", "content": "Trong quá trình đánh giá và phân loại giai đoạn ung thư lưỡi dựa trên hệ thống TNM, chỉ số T1 biểu thị khối u có kích thước đường kính dưới 2cm, chỉ số N1 định danh sự xuất hiện của hạch đơn cùng bên với đường kính dưới 3cm, đồng thời chỉ số M1 phản ánh rõ các biểu hiện tổn thương di căn xa."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "T | N | M\nT1: Khối u ĐK < 2cm | N1 : Xác định được hạch đơn cùng bên <3cm | M1 : Có biểu hiện di căn xa"}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "- Tổn thương mất mô cứng của răng có thể rất nhỏ chỉ xác định được khi thăm khám với dấu hiệu mắc thám châm hoặc biểu hiện rõ hình ảnh lỗ sâu với các đặc điểm sau:"}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "- Trong một số trường hợp, có thể xác định được các tổn thương là yếu tố kích thích."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "Nang tuyến nước bọt dưới hàm và dưới lưỡi có các dấu hiệu lâm sàng khá điển hình và không cần chẩn đoán phân biệt."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["49. UNG THƯ LƯỠI", "III. CHẨN ĐOÁN", "2. Chẩn đoán giai đoạn: Sử dụng hệ thống TNM."]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["4. SÂU RĂNG SỮA", "III. CHẨN ĐOÁN", "2. Chẩn đoán sâu răng giai đoạn hình thành lỗ sâu"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["48. ĐAU DÂY THẦN KINH V", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1. Lâm sàng", "1.1.2. Cơ năng", "b. Tính chất cơn đau"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["27. NANG TUYẾN NƯỚC BỌT DƯỚI HÀM VÀ DƯỚI LƯỠI", "III. CHẨN ĐOÁN", "2. Chẩn đoán phân biệt"]}]}
