{"question": "Phương pháp điều trị phẫu thuật nào được áp dụng?", "claim": "Điều trị bao gồm phẫu thuật cắt xương ở bên xương hàm không bị thương tổn hoặc kéo dài bên bị thương tổn.", "internal_evidence": [{"evidence_id": "R1", "content": "Phương pháp điều trị bao gồm phẫu thuật cắt xương ở bên xương hàm không bị thương tổn hoặc phẫu thuật kéo dài bên bị thương tổn. Liệu pháp chỉnh nha trước phẫu thuật giúp tối ưu hóa kết quả (1)."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "Chuẩn bị vật liệu nẹp mềm theo hướng dẫn của nhà sản xuất, đặc biệt chú ý sử dụng tỷ lệ chất nền và chất xúc tác được khuyến nghị và độ trộn chính xác; dùng các ngón tay đeo găng tay ẩm lăn hỗn hợp bột nhão thu được thành hình trụ (hình xúc xích)."}, {"quote_id": "P1.Q2", "evidence_id": "P1", "text": "Duy trì răng ở vị trí trong ổ răng."}, {"quote_id": "P1.Q3", "evidence_id": "P1", "text": "Làm 2 dải dán nhỏ. Đặt 1 dải trên bề mặt má và 1 dải trên bề mặt lưỡi/vòm miệng của răng cấy ghép lại, kéo dài các dải trên 1 hoặc 2 răng ở mỗi bên. Không che phủ bề mặt khớp cắn của răng."}, {"quote_id": "P1.Q4", "evidence_id": "P1", "text": "Nhẹ nhàng làm phẳng bề mặt của bột trét trong khi xoa vào các khoảng trống giữa các răng."}, {"quote_id": "P1.Q5", "evidence_id": "P1", "text": "Nếu cả hai bên của răng không thể được che phủ, chỉ đặt nẹp ở bên hàm."}, {"quote_id": "P1.Q6", "evidence_id": "P1", "text": "Nếu nẹp tạm thời không hiệu quả, hãy đưa bệnh nhân trực tiếp đến nha sĩ để áp dụng các phương pháp nẹp tiên tiến hơn (ví dụ: nẹp bằng dây và nẹp bằng nhựa liên kết)."}, {"quote_id": "P1.Q7", "evidence_id": "P1", "text": "Sau khi cấy ghép lại, cần chụp X-quang răng để xác định tổn thương liên quan."}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "Điều trị có thể bao gồm phẫu thuật cắt lồi cầu nếu dính khớp trong khớp hoặc phẫu thuật cắt bỏ một phần xương nhánh nếu mỏm quạ và cung gò má cũng bị thương tổn (1, 2). Các bài tập há hàm phải được tiếp tục sau khi phẫu thuật chỉnh sửa để duy trì khả năng vận động (3)."}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "Đĩa khớp bị dịch chuyển về phía trước do cơ chế hàm bất thường; đĩa có thể vẫn bị dịch chuyển (không có nắn chỉnh) hoặc trở lại (có nắn chỉnh)."}, {"quote_id": "P3.Q2", "evidence_id": "P3", "text": "Trật đĩa khớp có nắn chỉnh thường biểu hiện bằng tiếng kêu lách cách, hàm lệch về phía bị thương tổn khi há miệng và đau khi sử dụng hàm (chẳng hạn như nhai)."}, {"quote_id": "P3.Q3", "evidence_id": "P3", "text": "Trật đĩa khớp không có nắn chỉnh không biểu hiện bằng tiếng kêu lách cách/lách cách, nhưng khả năng há hàm tối đa bị giới hạn ở mức ≤ 30 mm và hàm lệch về phía bị thương tổn."}, {"quote_id": "P3.Q4", "evidence_id": "P3", "text": "Các tổ chức xung quanh cũng có thể viêm đau (viêm bao khớp)."}, {"quote_id": "P3.Q5", "evidence_id": "P3", "text": "Thuốc giảm đau, máng, và các bài tập chuyển động hàm thụ động có thể hỗ trợ điều trị, nhưng đôi khi yêu cầu phải phẫu thuật."}], "public_sources": [{"evidence_id": "P1", "title": "Cách đặt răng vào chỗ cũ và nẹp răng bị bật ra khỏi ổ răng", "heading_path": ["Mô tả từng bước về việc đặt răng vào chỗ cũ và nẹp răng bị bật ra khỏi ổ răng"]}, {"evidence_id": "P2", "title": "Dính Khớp Thái dương Hàm(TMJ)", "heading_path": []}, {"evidence_id": "P3", "title": "Di lệch Đĩa Nội Khớp Thái dương Hàm (TMJ)", "heading_path": ["Những điểm chính"]}]}
