{"question": "U tuyến đa hình trong miệng thường xuất hiện phổ biến nhất ở vị trí nào và có phải là ung thư ác tính không?", "claim": "U tuyến đa hình là loại u ác tính xuất hiện phổ biến nhất ở vùng niêm mạc sàn miệng.", "internal_evidence": [{"evidence_id": "I1", "content": "Khuyến cáo điều trị ngoại khoa đối với các khối u tuyến trong khoang miệng yêu cầu phải xác định rõ ranh giới mô học trước khi tiến hành phẫu thuật cắt bỏ."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "U tuyến đa hình là loại ung thư lành tính trong miệng phổ biến nhất. Niêm mạc ở hàm ếch là vị trí xuất hiện phổ biến nhất."}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "U tuyến đa hình là loại ung thư lành tính trong miệng phổ biến nhất. Niêm mạc ở hàm ếch là vị trí xuất hiện phổ biến nh"}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "U tuyến đa hình là loại ung thư lành tính trong miệng phổ biến nhất. Niêm mạc ở hàm ếch là vị trí xuất hiện phổ biến nh"}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "U tuyến đa hình là loại ung thư lành tính trong miệng phổ biến nhất. Niêm mạc ở hàm ếch là vị trí xuất hiện phổ biến nhất."}], "public_sources": [{"evidence_id": "P1", "title": "Các u ở miệng", "heading_path": ["Nguyên nhân U ở miệng", "Các u miệng lành tính"]}, {"evidence_id": "P2", "title": "Các u ở miệng", "heading_path": ["Nguyên nhân U ở miệng", "Các u miệng lành tính"]}, {"evidence_id": "P3", "title": "Các u ở miệng", "heading_path": ["Nguyên nhân U ở miệng", "Các u miệng lành tính"]}, {"evidence_id": "P4", "title": "Các u ở miệng", "heading_path": ["Nguyên nhân U ở miệng", "Các u miệng lành tính"]}]}
