{"question": "Quy trình thực hiện test há miệng có lực kháng trong khám cắn khớp và hệ thống nhai được tiến hành như thế nào?", "claim": "Khi thực hiện test há miệng có lực kháng, bác sĩ đặt lòng bàn tay dưới cằm bệnh nhân tạo lực đóng hàm, tay kia đỡ chỏm đầu và yêu cầu bệnh nhân há miệng chống lại để kích hoạt bó dưới cơ chân bướm ngoài.", "internal_evidence": [{"evidence_id": "I1", "content": "Để thực hiện test há miệng có lực kháng, bác sĩ đặt lòng bàn tay dưới cằm bệnh nhân tạo lực đóng hàm, tay kia giữ cố định vùng trán. Bệnh nhân được yêu cầu há miệng chống lại lực này nhằm mục đích kiểm tra sức mạnh của cơ thái dương, thay vì kích hoạt bó dưới cơ chân bướm ngoài."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "- Đặt vật lồi cầu sao cho chỏm khớp nằm đúng vị trí, dùng vít cố định lồi cầu vào phần cành cao xương hàm dưới đã được chuẩn bị."}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "+ Nếu đặt 1 ngón tay ở thành bên hầu, các ngón khác đặt sau và dưới góc hàm có thể phát hiện thấy mềm lún hoặc có dấu hiệu chuyển sóng."}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "- Tạo lập lại tương quan hai hàm lý tưởng nhất là khớp cắn loại I cả răng hàm lớn và răng nanh, nếu không thì ít nhất phải đạt được tương quan răng nanh loại I."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "+ Đặt dây cung thích hợp."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["57. DÍNH KHỚP THÁI DƯƠNG HÀM", "IV. ĐIỀU TRỊ", "2. Điều trị cụ thể", "2.2. Điều trị bằng phẫu thuật.", "b. Tạo hình khe khớp và sử dụng vật liệu thay thế."]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["34. ÁP XE THÀNH BÊN HỌNG", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1. Lâm sàng", "b. Tại chỗ"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["18. SAI KHỚP CẮN LOẠI II TIỂU LOẠI II DO RĂNG", "IV. ĐIỀU TRỊ", "1. Nguyên tắc"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["20 . KHỚP CẮN HỞ", "IV. ĐIỀU TRỊ", "2. Điều trị cụ thể", "2.2. Khớp cắn hở do xương hàm", "b. Bệnh nhân trưởng thành"]}]}
