{"question": "Dấu hiệu lâm sàng nào giúp xác định chẩn đoán gãy toàn bộ xương hàm trên dạng gãy ngang?", "claim": "Chẩn đoán xác định gãy ngang trong trường hợp gãy toàn bộ xương hàm trên dựa vào dấu hiệu có sự di động của xương hàm trên.", "internal_evidence": [{"evidence_id": "I1", "content": "Trong quá trình thăm khám lâm sàng các chấn thương vùng hàm mặt, để chẩn đoán xác định tình trạng gãy ngang xương hàm trên, bác sĩ cần dựa vào triệu chứng đặc trưng là sự di động của toàn bộ khối xương hàm trên khi thực hiện thao tác kiểm tra."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "Nang tuyến nước bọt dưới hàm và dưới lưỡi có các dấu hiệu lâm sàng khá điển hình và không cần chẩn đoán phân biệt."}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "Chẩn đoán xác định dựa vào các triệu chứng lâm sàng, cận lâm sàng và tính chất dịch tễ."}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "+ Có dấu hiệu di động xương hàm trên."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "- Sử dụng khí cụ có máng cắn phía sau tạo lực tác động làm lún các răng sau, làm cho xương hàm dưới xoay ra trước và lên trên làm đóng cắn hở, đồng thời hạn chế sự phát triển của xương hàm theo chiều đứng."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["27. NANG TUYẾN NƯỚC BỌT DƯỚI HÀM VÀ DƯỚI LƯỠI", "III. CHẨN ĐOÁN", "2. Chẩn đoán phân biệt"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["43. VIÊM TUYẾ N NƯỚ C BỌ T MANG TAI MẠ N TÍ NH", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["55. GÃY XƯƠNG HÀM TRÊN", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.2. Gãy toàn bộ", "b. Gãy ngang"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["20 . KHỚP CẮN HỞ", "IV. ĐIỀU TRỊ", "2. Điều trị cụ thể", "2.2. Khớp cắn hở do xương hàm", "a. Bệnh nhân đang trong thời kỳ tăng trưởng"]}]}
