{"question": "Viêm tủy có hồi phục cần được chẩn đoán phân biệt với những bệnh lý nào?", "claim": "Viêm tủy có hồi phục được chẩn đoán phân biệt với sâu ngà sâu và viêm tủy không hồi phục dựa trên các dấu hiệu lâm sàng và cận lâm sàng.", "internal_evidence": [{"evidence_id": "I1", "content": "Khi đánh giá các bệnh lý tủy răng, nhóm bệnh nhân viêm tủy có hồi phục cần được phân loại kỹ lưỡng so với nhóm sâu ngà sâu và nhóm viêm tủy không hồi phục dựa trên các trắc nghiệm nhạy cảm và triệu chứng lâm sàng."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "Viêm tủy có hồi phục chẩn đoán phân biệt với sâu ngà sâu và viêm tủy không hồi phục: Dựa vào các dấu hiệu lâm sàng và cận lâm sàng."}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "Khớp cắn hở có các biểu hiện trên lâm sàng và X quang rõ rệt, vì vậy không cần chẩn đoán phân biệt."}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "Dính khớp thái dương hàm luôn có các triệu chứng lâm sàng và X quang rõ rệt nên không cần chẩn đoán phân biệt."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "Triệu chứng | Viêm tủy có hồi phục | Sâu ngà sâu | Viêm tủy không hồi phục\nĐau, ê buốt khi ăn các chất kích thích như nóng,lạnh, chua, ngọt… | Có đau nhưng sau khi hết kích thích thì còn đau buốt nhẹ hoặc hết đau ngay. | Ê buốt ngà khi có kích thích nóng, lạnh, chua, ngọt. Hết kích thích thì hết ê buốt. | Đau tăng lên. Khi hết các chất kích thích, đau vẫn tiếp tục kéo dài thêm."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["11. VIÊM TỦY RĂNG", "III. CHẨN ĐOÁN", "1. Viêm tủy có hồi phục", "1.2. Chẩn đoán phân biệt"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["20 . KHỚP CẮN HỞ", "III. CHẨN ĐOÁN", "2. Chẩn đoán phân biệt"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["57. DÍNH KHỚP THÁI DƯƠNG HÀM", "III. CHẨN ĐOÁN", "2 Chẩn đoán phân biệt"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["5. VIÊM TỦY RĂNG SỮA", "III. CHẨN ĐOÁN", "1. Viêm tủy răng sữa có hồi phục", "c. Chẩn đoán phân biệt"]}]}
