{"question": "Phương pháp hai tay theo Datuson xác định tương quan trung tâm yêu cầu bác sĩ ngồi ở vị trí mấy giờ?", "claim": "Khi thực hiện phương pháp hai tay theo Datuson để tìm tương quan trung tâm, bác sĩ cần ngồi ở vị trí từ 10 đến 11 giờ chếch phía sau bệnh nhân.", "internal_evidence": [{"evidence_id": "I1", "content": "Bác sĩ ngồi chếch phía sau bệnh nhân ở vị trí 10 - 11 giờ, đầu bệnh được gìm giữ giữa khung sườn và cánh tay để không di động."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "Để phòng bệnh viêm lợi do mảng bám răng cần thực hiện các biện pháp dưới đây:"}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "+ Đau nhức răng: đau tự nhiên, liên tục dữ dội, lan lên nửa đầu, đau tăng khi nhai, ít đáp ứng với thuốc giảm đau, bệnh nhân có thể xác định rõ vị trí răng đau."}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "+ Gõ ly tâm từng núm răng hoặc thực hiện nghiệm pháp cắn bệnh nhân đau."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "- X quang: có bơm thuốc cản quang ống tuyến thấy hình ảnh bàn tay ôm bong trên phim mặt thẳng."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["6. VIÊM LỢI LIÊN QUAN ĐẾN MẢNG BÁM RĂNG", "VI. PHÒNG BỆNH"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["12. VIÊM QUANH CUỐNG RĂNG", "III. CHẨN ĐOÁN", "1. Viêm quanh cuống cấp", "a. Lâm sàng"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["11. VIÊM TỦY RĂNG", "III. CHẨN ĐOÁN", "2. Viêm tủy không hồi phục", "2.1. Chẩn đoán xác định"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["46. U TUYẾN NƯỚC BỌT DƯỚI HÀM", "III. CHẨN ĐOÁN", "1 Chẩn đoán xác định", "1.2. Cận lâm sàng"]}]}
