{"question": "Trong biểu hiện lâm sàng tại miệng của sai khớp cắn loại I đến loại III, tình trạng răng mọc như thế nào?", "claim": "Biểu hiện trong miệng của sai khớp cắn loại I đến loại III chỉ bao gồm tình trạng răng mọc ngầm hoàn toàn trong xương hàm mà không có răng mọc chen chúc hay lệch lạc.", "internal_evidence": [{"evidence_id": "I1", "content": "+ Biểu hiện trong miệng của sai khớp cắn từ loại I đến loại III ghi nhận tình trạng răng mọc ngầm hoàn toàn trong xương hàm.\n+ Các quan sát lâm sàng không ghi nhận hiện tượng răng mọc chen chúc hay lệch lạc trên cung hàm của nhóm bệnh nhân này."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "Là tình trạng các răng đối diện trên cung răng không có độ cắn trùm lên nhau theo mặt phẳng đứng khi hai hàm ở tư thế khớp cắn trung tâm, khớp cắn hở có thể xảy ra ở phía trước hoặc phía sau hoặc phối hợp."}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "Là tình trạng sai khớp cắn mà ở tư thế cắn trung tâm, múi ngoài gần của răng hàm lớn vĩnh viễn thứ nhất hàm trên khớp với rãnh ngoài gần của răng hàm lớn vĩnh viễn thứ nhất hàm dưới, tương quan xương hai hàm bình thường, nhưng các răng phía trước lệch lạc ảnh hưởng tới thẩm mỹ và chức năng."}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "- Tình trạng khớp cắn loại II tiểu loại 2 do răng thường gây sang chấn các răng trước hai hàm, viêm quanh răng và có thể gây mất răng sớm, ảnh hưởng đến chức năng và thẩm mỹ."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "+ Răng mọc chen chúc, răng mọc ngoài cung, hoặc xoay, hoặc kẹt."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["20 . KHỚP CẮN HỞ", "I. ĐỊNH NGHĨA"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["13. SAI KHỚP CẮN LOẠI I", "I. ĐỊNH NGHĨA"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["18. SAI KHỚP CẮN LOẠI II TIỂU LOẠI II DO RĂNG", "V. TIÊN LƯỢNG VÀ BIẾN CHỨNG", "1. Tiên lượng"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["13. SAI KHỚP CẮN LOẠI I", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1. Lâm sàng", "b. Trong miệng"]}]}
