{"question": "Các biện pháp điều trị tại chỗ để loại trừ kích thích trong bệnh viêm quanh răng tiến triển chậm gồm những gì?", "claim": "Các biện pháp điều trị tại chỗ nhằm loại trừ các kích thích tại chỗ trong bệnh viêm quanh răng tiến triển chậm bao gồm hướng dẫn vệ sinh răng miệng.", "internal_evidence": [{"evidence_id": "I1", "content": "Việc áp dụng các biện pháp điều trị tại chỗ nhằm loại bỏ triệt để các yếu tố kích thích trong bệnh lý viêm quanh răng tiến triển chậm bao gồm việc hướng dẫn bệnh nhân cách thức duy trì vệ sinh răng miệng đúng cách."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "- Viêm quanh răng tiến triển chậm liên quan với sự tích tụ của mảng bám vi khuẩn hay liên quan chặt chẽ với tình trạng vệ sinh răng miệng."}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "- Khám răng miệng định kỳ để phát hiện các răng sâu, tổn thương viêm quanh răng, răng khôn mọc lệch để điều trị kịp thời."}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "Là tổn thương mô cứng của răng bao gồm tổn thương men răng hoặc tổn thương cả men và ngà răng hoặc tổn thương xương răng mà không phải do sâu răng và thường do nhiều nguyên nhân khác nhau. Nếu không điều trị kịp thời thì các tổn thương này có thể dẫn tới viêm tuỷ răng."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "+ Hướng dẫn vệ sinh răng miệng."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["7. VIÊM QUANH RĂNG TIẾN TRIỂN CHẬM", "II. NGUYÊN NHÂN"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["32. ÁP XE VÙNG SÀN MIỆNG", "VI. PHÒNG BỆNH"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["10. TỔN THƯƠNG MÔ CỨNG CỦA RĂNG KHÔNG DO SÂU", "I. ĐỊNH NGHĨA"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["7. VIÊM QUANH RĂNG TIẾN TRIỂN CHẬM", "IV. ĐIỀU TRỊ", "3. Các biện pháp điều trị tại chỗ", "a. Loại trừ các kích thích tại chỗ"]}]}
