{"question": "Biểu hiện lâm sàng tại chỗ của niêm mạc má và tiền đình trong viêm tấy lan tỏa vùng hàm mặt là gì?", "claim": "Trong bệnh viêm tấy lan tỏa vùng hàm mặt, niêm mạc má và tiền đình thường xuất hiện tình trạng nề, mang dấu răng và có cặn tơ huyết bẩn.", "internal_evidence": [{"evidence_id": "I1", "content": "Trong nhóm bệnh nhân viêm tấy lan tỏa vùng hàm mặt, kết quả thăm khám ghi nhận niêm mạc má và vùng tiền đình miệng thường biểu hiện tình trạng nề căng, hằn rõ dấu răng và có lớp cặn tơ huyết bẩn bám trên bề mặt."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "Là tình trạng tổn thương mô mềm vùng hàm mặt do chấn thương với một hoặc các biểu hiện như bầm tím, đụng giập, rách, chảy máu, thiếu hổng mô.…"}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "- Viêm lợi: là biểu hiện đặc trưng của viêm quanh răng tiến triển chậm. Viêm lợi là do tích tụ mảng bám răng. Viêm lợi vớ i cá c biể u hiệ n là lợi thường sưng nề nhẹ đến trung bình và có biểu hiện biến đổi mầu sắc từ hồ ng nhạ t sang màu đỏ, lợi dính mất cấu trúc da cam. Có thay đổi hình thể bề mặt lợi như các bờ lợi không còn"}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "- Thể lâm sàng hiếm gặp là nang nhái ở cổ, xảy ra khi nang xuyên qua cơ hàm móng và biểu hiện thành khối phồng ở vùng cổ."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "+ Niêm mạc má, tiền đình nề, mang dấu răng, có cặn tơ huyết bẩn."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["53. CHẤN THƯƠNG PHẦN MỀM VÙNG HÀM MẶT", "I. ĐỊNH NGHĨA"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["7. VIÊM QUANH RĂNG TIẾN TRIỂN CHẬM", "III. CHẨN ĐOÁN", "1. Ch ẩn đoán xác định", "a. Lâm sàng"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["26. NANG NHÁI SÀN MIỆNG", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1 Lâm sàng"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["35. VIÊM TẤY LAN TỎA VÙNG HÀM MẶT", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1. Lâm sàng", "b. Tại chỗ"]}]}
