{"question": "Chẩn đoán xác định chấn thương phần mềm vùng hàm mặt dựa trên những yếu tố nào?", "claim": "Việc chẩn đoán xác định chấn thương phần mềm vùng hàm mặt chủ yếu dựa vào các triệu chứng lâm sàng, trong một số trường hợp có thể kết hợp thêm cận lâm sàng.", "internal_evidence": [{"evidence_id": "I1", "content": "Quá trình chẩn đoán xác định các tổn thương chấn thương phần mềm vùng hàm mặt chủ yếu dựa vào việc đánh giá các triệu chứng lâm sàng thông qua thăm khám thực thể, kết hợp khai thác bệnh sử và chỉ định thêm các phương pháp cận lâm sàng cần thiết trong từng trường hợp cụ thể."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "1.Chẩn đoán xác định Chủ yếu dựa trên cá c triệ u chứ ng lâm sà ng."}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "- Trong một số trường hợp, có thể xác định được các tổn thương là yếu tố kích thích."}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "Tình trạng cắn chéo luôn có các triệu chứng lâm sàng và cận lâm sàng rõ rệt, vì vậy không cần chẩn đoán phân biệt với các rối loạn khớp cắn khác."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "Chủ yếu dự a trên cá c triệ u chứ ng lâm sà ng , một số trường hợp có thể kết hợp cận lâm sàng."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["6. VIÊM LỢI LIÊN QUAN ĐẾN MẢNG BÁM RĂNG", "III. CHẨN ĐOÁN"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["48. ĐAU DÂY THẦN KINH V", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1. Lâm sàng", "1.1.2. Cơ năng", "b. Tính chất cơn đau"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["21. CẮN CHÉO", "III. CHẨN ĐOÁN", "3. Chẩn đoán phân biệt"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["53. CHẤN THƯƠNG PHẦN MỀM VÙNG HÀM MẶT", "III. CHẨ N ĐOÁ N", "1. Chẩ n đoá n xá c định"]}]}
