{"question": "Phương pháp cận lâm sàng nào có giá trị cao nhất trong chẩn đoán u tuyến nước bọt dưới hàm?", "claim": "Trong chẩn đoán cận lâm sàng u tuyến nước bọt dưới hàm, phương pháp sinh thiết có giá trị hơn so với chọc hút.", "internal_evidence": [{"evidence_id": "I1", "content": "Đối với các bệnh lý u tuyến nước bọt dưới hàm, việc đánh giá cận lâm sàng thông qua phương pháp sinh thiết tổ chức học mang lại giá trị chẩn đoán xác định cao hơn đáng kể so với phương pháp chọc hút tế bào bằng kim nhỏ."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "- Giải phẫu bệnh lý: sinh thiết có giá trị hơn chọc hút. 2.Chẩn đoán phân biệt"}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "- Chỉ định: Nang có kích thước vừa phải và liên quan với tuyến nước bọt dưới lưỡi."}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "+ Số đo góc răng cửa hàm trên với mặt phẳng khẩu cái: có giá trị lớn hơn bình thường."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "+ Số đo góc răng cửa dưới với mặt phẳng hàm dưới: nhỏ hơn giá trị bình thường. 2.Chẩn đoán phân biệt"}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["46. U TUYẾN NƯỚC BỌT DƯỚI HÀM", "III. CHẨN ĐOÁN", "1 Chẩn đoán xác định", "1.2. Cận lâm sàng"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["26. NANG NHÁI SÀN MIỆNG", "IV. ĐIỀU TRỊ", "2. Điều trị cụ thể", "2.2. Phẫu thuật cắt bỏ nang và tuyến nước bọt dưới lưỡi"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["22. SAI KHỚP CẮN LOẠI III DO KÉM PHÁT TRIỂN XƯƠNG HÀM TRÊN", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "b. X quang"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["22. SAI KHỚP CẮN LOẠI III DO KÉM PHÁT TRIỂN XƯƠNG HÀM TRÊN", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "b. X quang"]}]}
