ding_path": ["48. ĐAU DÂY THẦN KINH V", "IV. ĐIỀU TRỊ", "2. Điều trị cụ thể", "2.2. Điều trị triệu chứng", "2.2.1 Nội khoa"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["6. VIÊM LỢI LIÊN QUAN ĐẾN MẢNG BÁM RĂNG", "IV. ĐIỀU TRỊ"]}], "conversation": [{"role": "user", "content": "Bác sĩ ơi, lợi phì đại xơ hóa có cần phẫu thuật ngay không hay dùng thuốc trước?"}, {"role": "assistant", "content": "Chắc là điều trị bằng thuốc kháng viêm trước rồi mới phẫu thuật sau cùng."}]}
