{"question": "Cần xử lý như thế nào đối với các răng có độ lẹm quá lớn trong điều trị tiền phục hình mất răng từng phần?", "claim": "Bác sĩ cần tiến hành mài chỉnh những răng có độ lẹm quá lớn theo khảo sát trên song song kế để chuẩn bị cho phục hình.", "internal_evidence": [{"evidence_id": "I1", "content": "Trong quá trình lập kế hoạch điều trị tiền phục hình mất răng từng phần, việc khảo sát trên song song kế là bắt buộc nhằm phát hiện các răng có độ lẹm quá lớn, từ đó giúp bác sĩ đưa ra chỉ định mài chỉnh hợp lý trước khi tiến hành lắp phục hình."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "+ Hoặc tương quan loại I răng hàm lớn thứ nhất và răng nanh. Một hoặc một số răng có độ cắn chìa đảo ngược hoặc có giá trị bằng 0 trong mối tương quan hướng môi - lưỡi giữa các răng phía trước cuả hàm trên và hàm dưới."}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "- Mài chỉnh những răng có độ lẹm quá lớn theo khảo sát trên song song kế."}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "- Đối với các trường hợp tổn thương sâu răng sớm thì cung cấp các yếu tố nhằm tăng cường quá trình tái khoáng, ngăn chặn hủy khoáng để phục hồi các tổn thương."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "- Phẫu thuật chỉnh hình xương hàm dưới: áp dụng trong các trường hợp nặng không thể điều trị bù trừ bằng nắn chỉnh răng đơn thuần."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["21. CẮN CHÉO", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1. Cắn chéo phía trước", "1.1.1. Lâm sàng", "b. Trong miệng"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["3. MẤT RĂNG TỪNG PHẦN", "IV. ĐIỀU TRỊ", "2. Điều trị cụ thể", "2.1. Điều trị tiền phục hình"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["4. SÂU RĂNG SỮA", "IV. ĐIỀU TRỊ", "1. Nguyên tắc"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["15. SAI KHỚP CẮN LOẠI II DO KÉM PHÁT TRIỂN XƯƠNG HÀM DƯỚI", "IV. ĐIỀU TRỊ", "2. Điều trị cụ thể", "2.2. Bệnh nhân đã hết thời kỳ tăng trưởng"]}]}
