{"question": "Cận lâm sàng nào được sử dụng để xác định chẩn đoán u hỗn hợp tuyến nước bọt mang tai?", "claim": "Để xác định chẩn đoán xác định u hỗn hợp tuyến nước bọt mang tai, cần thực hiện cận lâm sàng xét nghiệm mô bệnh học.", "internal_evidence": [{"evidence_id": "I1", "content": "Nhóm nghiên cứu lâm sàng ghi nhận và so sánh các phương pháp chẩn đoán u tuyến nước bọt mang tai, trong đó xét nghiệm mô bệnh học đóng vai trò là cận lâm sàng cốt lõi và bắt buộc để xác định chính xác bản chất u hỗn hợp."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "T | N | M\nT0: Khối u không xác định được trên lâm sàng | N0: Không có hạch | M0: Chưa có di căn xa"}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "Tình trạng cắn chéo luôn có các triệu chứng lâm sàng và cận lâm sàng rõ rệt, vì vậy không cần chẩn đoán phân biệt với các rối loạn khớp cắn khác."}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "- Xét nghiệm mô bệnh học"}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "Nang tuyến nước bọt dưới hàm và dưới lưỡi có các dấu hiệu lâm sàng khá điển hình và không cần chẩn đoán phân biệt."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["49. UNG THƯ LƯỠI", "III. CHẨN ĐOÁN", "2. Chẩn đoán giai đoạn: Sử dụng hệ thống TNM."]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["21. CẮN CHÉO", "III. CHẨN ĐOÁN", "3. Chẩn đoán phân biệt"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["45. U HỖ N HỢ P TUYẾ N NƯỚ C BỌ T MANG TAI", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.2. Cận lâm sàng"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["27. NANG TUYẾN NƯỚC BỌT DƯỚI HÀM VÀ DƯỚI LƯỠI", "III. CHẨN ĐOÁN", "2. Chẩn đoán phân biệt"]}]}
