{"question": "Quy trình thiết kế hàm khung kim loại trong phục hình răng giả tháo lắp từng phần được thực hiện ở đâu?", "claim": "Thiết kế hàm khung kim loại trong phục hình răng giả tháo lắp từng phần được thực hiện trên mẫu thạch cao.", "internal_evidence": [{"evidence_id": "I1", "content": "Trong quá trình lập kế hoạch phục hình răng giả tháo lắp từng phần, các kỹ thuật viên và bác sĩ nha khoa thực hiện việc lên kế hoạch cũng như thiết kế chi tiết khung kim loại trực tiếp trên mẫu hàm làm bằng thạch cao của bệnh nhân để đảm bảo độ chính xác."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "+ Khảo sát mẫu hàm, xác định răng đặt móc, hướng lắp và khung sơ khảo trên song song kế."}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "- Can thiệp phẫu thuật chỉnh hình xương: Trong các trường hợp kém phát triển xương hàm trên nặng không thể điều trị bù trừ bằng nắn chỉnh răng đơn thuần được thì phải kết hợp chỉnh hình xương hàm trên."}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "+ Hoặc tương quan loại I răng hàm lớn thứ nhất và răng nanh. Một hoặc một số răng có độ cắn chìa đảo ngược hoặc có giá trị bằng 0 trong mối tương quan hướng môi - lưỡi giữa các răng phía trước cuả hàm trên và hàm dưới."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "+ Thiết kế hàm khung trên mẫu thạch cao."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["3. MẤT RĂNG TỪNG PHẦN", "IV. ĐIỀU TRỊ", "2. Điều trị cụ thể", "2.2. Phục hình răng bằng Hàm giả tháo lắp", "b. Hàm khung kim loại"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["22. SAI KHỚP CẮN LOẠI III DO KÉM PHÁT TRIỂN XƯƠNG HÀM TRÊN", "VI. ĐIỀU TRỊ", "b. Bệnh nhân hết thời kỳ tăng trưởng"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["21. CẮN CHÉO", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1. Cắn chéo phía trước", "1.1.1. Lâm sàng", "b. Trong miệng"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["3. MẤT RĂNG TỪNG PHẦN", "IV. ĐIỀU TRỊ", "2. Điều trị cụ thể", "2.2. Phục hình răng bằng Hàm giả tháo lắp", "b. Hàm khung kim loại"]}]}
