{"question": "Bệnh nhân bị viêm lợi loét hoại tử cấp tính cần được chỉ định điều trị như thế nào ở lần khám đầu tiên và sử dụng nước súc miệng gì?", "claim": "Trong lần điều trị đầu tiên cho viêm lợi loét hoại tử cấp tính, cần giới hạn ở các vùng liên quan tới tình trạng cấp tính và hướng dẫn bệnh nhân xúc miệng bằng dung dịch Chlohexidine 0,12% hai lần mỗi ngày.", "internal_evidence": [{"evidence_id": "I1", "content": "Phác đồ điều trị cho trường hợp viêm lợi loét hoại tử cấp tính yêu cầu bác sĩ thực hiện việc làm sạch nhẹ nhàng tại các vùng đang có triệu chứng cấp tính nhằm giảm đau và ngăn ngừa tổn thương lan rộng. Bệnh nhân cần được kê đơn hướng dẫn sử dụng nước súc miệng chứa hoạt chất kháng khuẩn phù hợp theo chỉ định lâm sàng."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "+ Dịch chuyển các răng để có được tương quan hai hàm ở mức tối ưu. Có thể phối hợp sử dụng chun liên hàm loại III."}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "+ Xúc miệng Chlohexidine 0,12%, mỗi ngày 2 lần."}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "+ Trong giai đoạn điều trị này, ưu tiên điều trị các cấp cứu về răng miệng như viêm tủy răng cấp, viêm quanh cuống răng cấp, viêm quanh thân răng cấp, áp xe lợi, áp xe quanh răng cấp."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "- Mặc dù khả năng miễn dịch của cơ thể có thể thay đổi nhưng viêm quanh răng tiến triển chậm hầu như không liên quan với các thiếu hụt miễn dịch và tình trạng toàn thân bấ t thường."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["22. SAI KHỚP CẮN LOẠI III DO KÉM PHÁT TRIỂN XƯƠNG HÀM TRÊN", "VI. ĐIỀU TRỊ", "b. Bệnh nhân hết thời kỳ tăng trưởng"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["8. VIÊM LỢ I LOÉ T HOẠ I TỬ CẤ P TÍ NH", "IV. ĐIỀ U TRỊ", "1. Lần 1: Điều trị phải được giới hạn ở các vùng liên quan tới tình trạng cấp tính."]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["7. VIÊM QUANH RĂNG TIẾN TRIỂN CHẬM", "IV. ĐIỀU TRỊ", "2. Phác đồ điều trị"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["7. VIÊM QUANH RĂNG TIẾN TRIỂN CHẬM", "II. NGUYÊN NHÂN"]}]}
