{"question": "Trong giai đoạn hàm răng hỗn hợp, trường hợp cắn chéo có thể được chỉ định điều trị cụ thể bằng khí cụ gì theo hướng dẫn của Bộ Y tế?", "claim": "Trong giai đoạn hàm răng hỗn hợp, điều trị cắn chéo có thể sử dụng khí cụ frankel III theo quy chuẩn hướng dẫn.", "internal_evidence": [{"evidence_id": "I1", "content": "Trong giai đoạn hàm răng hỗn hợp, khi trẻ gặp tình trạng cắn chéo răng trước hoặc răng sau, bác sĩ chỉnh nha cần tiến hành thăm khám lâm sàng kỹ lưỡng và chỉ định điều trị bằng khí cụ frankel III theo đúng quy chuẩn hướng dẫn nhằm kích thích sự phát triển của xương hàm trên và điều chỉnh tương quan hai hàm."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "- Phẫu thuật chỉnh hình xương hai hàm: áp dụng trong các trường hợp nặng không thể điều trị bù trừ bằng nắn chỉnh răng đơn thuần."}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "Tùy từng trường hợp cụ thể mà có thể áp dụng một trong ba biện pháp điều trị dưới đây:"}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "- Sử dụng khí cụ có máng cắn phía sau tạo lực tác động làm lún các răng sau, làm cho xương hàm dưới xoay ra trước và lên trên làm đóng cắn hở, đồng thời hạn chế sự phát triển của xương hàm theo chiều đứng."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "+ Dùng khí cụ frankel III…"}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["16. SAI KHỚP CẮN LOẠI II DO XƯƠNG HAI HÀM.", "IV. ĐIỀU TRỊ", "2. Điều trị cụ thể", "2.2. Bệnh nhân đã qua thời kỳ tăng trưởng"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["27. NANG TUYẾN NƯỚC BỌT DƯỚI HÀM VÀ DƯỚI LƯỠI", "IV. ĐIỀU TRỊ", "2. Điều trị cụ thể"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["20 . KHỚP CẮN HỞ", "IV. ĐIỀU TRỊ", "2. Điều trị cụ thể", "2.2. Khớp cắn hở do xương hàm", "a. Bệnh nhân đang trong thời kỳ tăng trưởng"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["21. CẮN CHÉO", "IV. ĐIỀU TRỊ", "2. Điều trị cụ thể", "b. Giai đoạn hàm răng hỗn hợp"]}]}
