{"question": "Vết thương xây sát vùng hàm mặt cần được băng bó bằng loại thuốc nào?", "claim": "Vết thương xây sát vùng hàm mặt phải được băng bó hoàn toàn bằng gạc khô vô khuẩn tuyệt đối, tuyệt đối không dùng các loại mỡ kháng sinh hay thuốc tê.", "internal_evidence": [{"evidence_id": "I1", "content": "Kế hoạch điều trị đề xuất chỉ sử dụng băng gạc khô vô trùng cho các vết thương xây sát ngoài da vùng hàm mặt để tránh kích ứng."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "+ Băng bằng mỡ kháng sinh có phủ Lidocaine."}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "- Dùng nước súc miệng có tác dụng kìm khuẩn hoặc sát khuẩn cho những người không thể làm sạch mảng bám răng bằng các biện pháp cơ học như bị tật, đang phẫu thuật vùng miệng, hàm mặt, mang khí cụ nắn chỉnh răng."}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "Viêm tấy tỏa lan vùng hàm mặt có các biểu hiện lâm sàng rõ và tiến triển nhanh, không cần chẩn đoán phân biệt."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "+ Vùng tổn thương sâu răng sớm xuất hiện các vết trắng đục khi thổi khô bề mặt."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["53. CHẤN THƯƠNG PHẦN MỀM VÙNG HÀM MẶT", "IV. ĐIỀ U TRỊ", "2. Điều trị cụ thể", "2.1. Vết thương xây sát"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["6. VIÊM LỢI LIÊN QUAN ĐẾN MẢNG BÁM RĂNG", "IV. ĐIỀU TRỊ"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["35. VIÊM TẤY LAN TỎA VÙNG HÀM MẶT", "III. CHẨN ĐOÁN", "2. Chẩn đoán phân biệt"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["4. SÂU RĂNG SỮA", "III. CHẨN ĐOÁN", "1. Chẩn đoán các tổn thương sâu răng sớm"]}]}
