{"question": "Biểu hiện tại chỗ ở vùng mặt của bệnh viêm tấy lan tỏa vùng hàm mặt là gì?", "claim": "Triệu chứng lâm sàng tại chỗ của bệnh viêm tấy lan tỏa vùng hàm mặt bao gồm hiện tượng mất các rãnh tự nhiên ở mặt.", "internal_evidence": [{"evidence_id": "I1", "content": "Thăm khám lâm sàng bệnh nhân mắc viêm tấy lan tỏa vùng hàm mặt cho thấy các biểu hiện tại chỗ rất rõ rệt ở vùng mặt. Dấu hiệu dễ nhận biết nhất là sự biến mất hoàn toàn của các rãnh tự nhiên trên bề mặt da do tình trạng phù nề lan tỏa."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "Là tình trạng tổn thương mô mềm vùng hàm mặt do chấn thương với một hoặc các biểu hiện như bầm tím, đụng giập, rách, chảy máu, thiếu hổng mô.…"}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "- Thể lâm sàng hiếm gặp là nang to đi từ vùng sàn miệng lấn qua cơ hàm móng và biểu hiện thành khối phồng ở vùng cổ."}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "+ Mất các rãnh tự nhiên ở mặt."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "+ Nếu mủ tụ ở sau vùng trâm: bệnh cảnh lâm sàng tương tự như nhiễm khuẩn máu. Bệnh nhân ít khi bị khít hàm, sưng bên ngoài cũng ít hơn so với áp xe ở trước trâm. Trong miệng thây sưng thành bên hầu."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["53. CHẤN THƯƠNG PHẦN MỀM VÙNG HÀM MẶT", "I. ĐỊNH NGHĨA"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["27. NANG TUYẾN NƯỚC BỌT DƯỚI HÀM VÀ DƯỚI LƯỠI", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1 Lâm sàng"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["35. VIÊM TẤY LAN TỎA VÙNG HÀM MẶT", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1. Lâm sàng", "b. Tại chỗ"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["34. ÁP XE THÀNH BÊN HỌNG", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1. Lâm sàng", "b. Tại chỗ"]}]}
