{"question": "Biểu hiện lâm sàng ở vùng ngách lợi tương ứng quanh cuống răng trong bệnh viêm quanh cuống mạn tính là gì?", "claim": "Vùng ngách lợi tương ứng quanh cuống răng bị viêm quanh cuống mạn có thể hơi nề, xuất hiện lỗ rò hoặc sẹo rò vùng cuống, thậm chí lỗ rò có thể ở ngoài da hoặc nền mũi.", "internal_evidence": [{"evidence_id": "I1", "content": "Phác đồ theo dõi lâm sàng bệnh lý viêm quanh cuống mạn tính cho thấy vùng ngách lợi tương ứng với vị trí chóp răng tổn thương thường có biểu hiện hơi nề. Tùy thuộc vào mức độ lan rộng của nang và áp xe, tại đây có thể xuất hiện lỗ rò hoặc vết sẹo rò nằm trong miệng, ngoài da hoặc lan đến vùng nền mũi."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "+ Vùng ngách lợi tương ứng quanh cuống răng có thể hơi nề, có lỗ rò hoặc sẹo rò vùng cuống. Đôi khi lỗ rò không ở trong hốc miệng mà ở ngoài da hoặc nền mũi tùy vị trí nang và áp xe."}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "- Tính chất khu trú: Bệnh viêm quanh răng tiến triển chậm thường có ở toàn bộ hai hàm mặc dù có một vài vùng có thể nặng hơn so với các vùng khác. Các vùng nặng hơn thường liên quan vớ i việ c kiểm soát mả ng bá m kém hơn như vùng chẽ chân răng hoặc các răng mọc sai vị trí."}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "Triệu chứng | Sâu răng sữa giai đoạn sớm | Thay đổi màu sắc răng không do sâu\nVị trí | - Hố rãnh mặt nhai, mặt gần, xa, mặt ngoài hoặc mặt trong các răng hàm sữa. - Mặt gần, xa, mặt ngoài hoặc mặt trong các răng cửa và răng nanh sữa. | Toàn bộ mặt răng, có thể ở một răng do bị chấn thương gây chết tủy, hoặc trên nhiều răng do thiểu sản men răng sữa, có tính chất đối xứng."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "+ Nếu mủ tụ ở vùng trước trâm thì thấy sưng đau dọc cơ ức đòn chũm.Khởi đầu vùng dưới hàm ,góc hàm có 1 khối sưng lớn, da trên khối sưng nóng đỏ hoặc tím, căng, nề, có thể thâm nhiễm lan rộng lên vùng mang tai.Lồi bờ nền xương hàm dưới bị xóa."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["12. VIÊM QUANH CUỐNG RĂNG", "III. CHẨN ĐOÁN", "3. Viêm quanh cuống mạn", "3.1. Chẩn đoán xác định", "a. Lâm sàng"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["7. VIÊM QUANH RĂNG TIẾN TRIỂN CHẬM", "III. CHẨN ĐOÁN", "1. Ch ẩn đoán xác định", "a. Lâm sàng"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["9. BỆNH SÂU RĂNG", "III. CHẨN ĐOÁN", "2. Chẩn đoán phân biệt"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["34. ÁP XE THÀNH BÊN HỌNG", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1. Lâm sàng", "b. Tại chỗ"]}]}
