{"question": "Biểu hiện lâm sàng của khớp cắn hở do răng thường xuất hiện ở những vị trí nào trên cung hàm?", "claim": "Khớp cắn hở do răng có thể có biểu hiện cắn hở cục bộ ở cả vùng răng trước và vùng răng sau trên cung hàm.", "internal_evidence": [{"evidence_id": "I1", "content": "Thực hành lâm sàng ghi nhận tình trạng khớp cắn hở do nguyên nhân từ răng có thể xuất hiện biểu hiện cắn hở cục bộ ở cả vùng răng trước lẫn vùng răng sau trên cung hàm của bệnh nhân."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "+ Có thể có biểu hiện cắn hở cục bộ ở cả vùng răng trước và răng sau."}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "+ Thói quen đẩy lưỡi: Khi lưỡi đặt ở vị trí ra trước và giữa các răng cửa trên và răng cửa dưới thường xuyên sẽ gây ra khớp cắn hở."}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "+ Có thể có biểu hiện cắn hở ở vùng các răng phía sau, nhưng các răng trước có tiếp xúc."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "Là tình trạng sai khớp cắn mà ở tư thế cắn trung tâm, múi ngoài gần của răng hàm lớn vĩnh viễn thứ nhất hàm trên khớp về phía gần so với rãnh ngoài gần của răng hàm lớn vĩnh viễn thứ nhất hàm dưới, xương hàm dưới lùi phía sau so với cấu trúc nền sọ, xương hàm trên ở vị trí bình thường."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["20 . KHỚP CẮN HỞ", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1. Khớp cắn hở do răng", "b. Lâm sàng"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["20 . KHỚP CẮN HỞ", "II. NGUYÊN NHÂN", "1. Loại cắn hở do răng"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["20 . KHỚP CẮN HỞ", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1. Khớp cắn hở do răng", "b. Lâm sàng"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["15. SAI KHỚP CẮN LOẠI II DO KÉM PHÁT TRIỂN XƯƠNG HÀM DƯỚI", "I. ĐỊNH NGHĨA"]}]}
