{"question": "Phương pháp phẫu thuật điều trị dính khớp thái dương hàm bằng tạo hình khớp có ghép sụn sườn tự thân gồm những bước cơ bản nào?", "claim": "Phương pháp phẫu thuật tạo hình khớp có ghép sụn sườn tự thân để điều trị dính khớp thái dương hàm bao gồm việc cắt bỏ khối dính và tạo hình ổ khớp.", "internal_evidence": [{"evidence_id": "I1", "content": "Trong quy trình phẫu thuật điều trị dính khớp thái dương hàm bằng phương pháp tạo hình khớp sử dụng sụn sườn tự thân, phẫu thuật viên thực hiện các bước kỹ thuật quan trọng gồm việc cắt bỏ triệt để khối xương dính để giải phóng vận động, sau đó tiến hành lấy và tạo hình mảnh ghép sụn sườn tự thân để tái thiết lập cấu trúc ổ khớp và chức năng ăn nhai cho người bệnh."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "Những răng bị tổn thương vùng cuống răng nếu không được điều trị kịp thời và đúng phương pháp, bệnh có thể gây nhiều biến chứng phức tạp, gây ảnh hưởng không nhỏ tới sức khỏe người bệnh."}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "+ Nước bọt: Dòng chảy và tốc độ chảy của nước bọt là yếu tố làm sạch tự nhiên để loại bỏ các mảnh vụn thức ăn còn sót lại. Tạo một lớp màng mỏng trên bề mặt của răng từ nước bọt có vai trò như một hàng rào bảo vệ men răng khỏi pH nguy cơ. Ngoài ra nước bọt còn có vai trò đệm làm giảm độ toan của môi trường quanh răng và có tác dụng đề kháng với sâu răng. Nước bọt còn là nguồn cung cấp các chất khoáng, hỗ trợ quá trình tái khoáng để có thể phục hồi các tổn thương sâu răng sớm."}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "- Cắt bỏ khối dính và tạo hình ổ khớp."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "+ Nước bọt Dòng chảy và tốc độ chảy của nước bọt là yếu tố làm sạch tự nhiên để loại bỏ các mảnh vụn thức ăn còn sót lại. Tạo một lớp màng mỏng trên bề mặt của răng từ nước bọt có vai trò như một hàng rào bảo vệ men răng khỏi pH nguy cơ. Ngoài ra nước bọt còn có vai trò đệm làm giảm độ toan của môi trường quanh răng và có tác dụng đề kháng với sâu răng. Nước bọt còn là nguồn cung cấp các chất khoáng, hỗ trợ quá trình tái khoáng để có thể phục hồi các tổn thương sâu răng sớm."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["12. VIÊM QUANH CUỐNG RĂNG", "V. BIẾN CHỨNG VÀ TIÊN LƯỢNG"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["4. SÂU RĂNG SỮA", "II. NGUYÊN NHÂN"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["57. DÍNH KHỚP THÁI DƯƠNG HÀM", "IV. ĐIỀU TRỊ", "2. Điều trị cụ thể", "2.2. Điều trị bằng phẫu thuật.", "a. Tạo hình khớp có ghép sụn sườn tự thân."]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["9. BỆNH SÂU RĂNG", "II . NGUYÊN NHÂN"]}]}
