{"question": "Cách xử trí đối với gãy xương gò má cung tiếp trong chẩn đoán lâm sàng là gì?", "claim": "Cần sử dụng dụng cụ thích hợp để nắn chỉnh, đưa các phần xương gãy về đúng vị trí giải phẫu trong chẩn đoán và điều trị gãy xương gò má cung tiếp.", "internal_evidence": [{"evidence_id": "I1", "content": "Phác đồ xử trí ngoại khoa đối với chấn thương gãy xương gò má cung tiếp yêu cầu phẫu thuật viên phải sử dụng các dụng cụ chuyên dụng thích hợp để thực hiện thao tác nắn chỉnh kín hoặc mở. Mục tiêu là đưa toàn bộ các mảnh xương gãy rời về lại đúng vị trí giải phẫu ban đầu, đảm bảo phục hồi biên độ vận động hàm và thẩm mỹ khuôn mặt."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "- Hóa trị liệu: có thể sử dụng trước phẫu thuật và phối hợp điều trị sau phẫu thuật."}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "- Can thiệp phẫu thuật chỉnh hình xương: Trong các trường hợp kém phát triển xương hàm trên nặng không thể điều trị bù trừ bằng nắn chỉnh răng đơn thuần được thì phải kết hợp chỉnh hình xương hàm trên."}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "- Dùng dụng cụ thích hợp nắn chỉnh đưa các phần xương gãy về đúng vị trí giải phẫu."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "1.2 Cận lâm sàng"}, {"quote_id": "P4.Q2", "evidence_id": "P4", "text": "Gãy xương gò má cung tiếp luôn có các triệu chứng lâm sàng và X quang rõ"}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["49. UNG THƯ LƯỠI", "IV. ĐIỀU TRỊ", "2. Điều trị cụ thể"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["22. SAI KHỚP CẮN LOẠI III DO KÉM PHÁT TRIỂN XƯƠNG HÀM TRÊN", "VI. ĐIỀU TRỊ", "b. Bệnh nhân hết thời kỳ tăng trưởng"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["56. GÃY XƯƠNG GÒ MÁ CUNG TIẾP", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1. Lâm sàng"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["56. GÃY XƯƠNG GÒ MÁ CUNG TIẾP", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1. Lâm sàng"]}]}
