{"question": "Triệu chứng gõ ngang của răng bị viêm tủy răng sữa có hồi phục khác gì so với sâu ngà sâu?", "claim": "Khi thực hiện gõ ngang trên răng sữa bị viêm tủy có hồi phục, bệnh nhân hoàn toàn không có cảm giác đau giống như trường hợp sâu ngà sâu.", "internal_evidence": [{"evidence_id": "I1", "content": "Sổ tay thực hành lâm sàng ghi nhận khi thực hiện thao tác gõ ngang trên bề mặt răng sữa bị viêm tủy có hồi phục, bệnh nhân hoàn toàn không có cảm giác đau đớn, tương tự như hiện tượng quan sát được ở các trường hợp tổn thương sâu ngà sâu."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "Triệu chứng | Viêm tủy có hồi phục | Sâu ngà sâu | Viêm tủy không hồi phục
Gõ dọc | Không đau. | Không đau. | Đau nhẹ."}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "Triệu chứng | Viêm tủy có hồi phục | Sâu ngà sâu | Viêm tủy không hồi phục
Đau, ê buốt tự nhiên | Đau tự nhiên xuất hiện thoáng qua. | Không có đau tự nhiên. | Đau tự nhiên từng cơn, đau nhiều về đêm."}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "- Các trường hợp đã hình thành lỗ sâu: nếu hàn phục hồi tốt đúng quy trình thì hoàn toàn có thể phục hồi được mô cứng của răng ngăn ngừa được các biến chứng."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "Triệu chứng | Viêm tủy có hồi phục | Sâu ngà sâu | Viêm tủy không hồi phục
Gõ ngang | Có thể có đau nhẹ. | Không đau. | Đau nhiều."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["5. VIÊM TỦY RĂNG SỮA", "III. CHẨN ĐOÁN", "1. Viêm tủy răng sữa có hồi phục", "c. Chẩn đoán phân biệt"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["5. VIÊM TỦY RĂNG SỮA", "III. CHẨN ĐOÁN", "1. Viêm tủy răng sữa có hồi phục", "c. Chẩn đoán phân biệt"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["4. SÂU RĂNG SỮA", "V. TIÊN LƯỢNG VÀ BIẾN CHỨNG", "1. Tiên lượng"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["5. VIÊM TỦY RĂNG SỮA", "III. CHẨN ĐOÁN", "1. Viêm tủy răng sữa có hồi phục", "c. Chẩn đoán phân biệt"]}]}
