{"question": "Tiên lượng điều trị áp xe vùng sàn miệng sẽ ra sao nếu chỉ thực hiện dẫn lưu mủ đơn thuần mà không điều trị răng nguyên nhân?", "claim": "Tiên lượng điều trị áp xe vùng sàn miệng luôn đạt kết quả tốt ngay cả khi chỉ thực hiện dẫn lưu mủ mà không cần quan tâm đến điều trị răng nguyên nhân.", "internal_evidence": [{"evidence_id": "I1", "content": "Bản nháp ghi nhận có thể tiến hành dẫn lưu mủ đơn độc để giải quyết ổ áp xe vùng sàn miệng mà không bắt buộc phải xử lý răng nguyên nhân."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "+ Nếu mủ tụ ở sau vùng trâm: bệnh cảnh lâm sàng tương tự như nhiễm khuẩn máu. Bệnh nhân ít khi bị khít hàm, sưng bên ngoài cũng ít hơn so với áp xe ở trước trâm. Trong miệng thây sưng thành bên hầu."}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "1.Tiên lượng Nếu dẫn lưu mủ phối hợp với điều trị răng nguyên nhân thì có kết quả điều trị tốt."}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "1.Tiên lượng Phẫu thuật cắt bỏ nang và tuyến nước bọt dưới hàm hoặc dưới lưỡi, hoặc phẫu thuật mở thông nang, nếu thực hiện đúng kỹ thuật thì đều cho kết quả tốt, không tái phát."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "- Dịch rỉ viêm: có thể có dịch rỉ viêm hoặc mủ ở túi lợi. Nếu trường hợp túi quanh răng bị bít kín lại thì mủ không thể dẫn lưu ra được và có thể hình thành áp xe quanh răng. Khi có á p xe quanh răng thì sẽ gây ra đau cho bệ nh nhân."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["34. ÁP XE THÀNH BÊN HỌNG", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1. Lâm sàng", "b. Tại chỗ"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["32. ÁP XE VÙNG SÀN MIỆNG", "V. TIÊN LƯỢNG VÀ BIẾN CHỨNG"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["27. NANG TUYẾN NƯỚC BỌT DƯỚI HÀM VÀ DƯỚI LƯỠI", "V. TIÊN LƯỢNG VÀ BIẾN CHỨNG"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["7. VIÊM QUANH RĂNG TIẾN TRIỂN CHẬM", "III. CHẨN ĐOÁN", "1. Ch ẩn đoán xác định", "a. Lâm sàng"]}]}
