{"question": "Quy trình phẫu thuật điều trị gãy xương gò má cung tiếp bao gồm các bước đóng vết thương phần mềm như thế nào?", "claim": "Trong phẫu thuật điều trị gãy xương gò má cung tiếp, phẫu thuật viên tiến hành khâu đóng phần mềm theo đúng các lớp giải phẫu.", "internal_evidence": [{"evidence_id": "I1", "content": "Trong quá trình phẫu thuật điều trị gãy xương gò má cung tiếp, phẫu thuật viên cần thực hiện thao tác khâu đóng mô mềm bên ngoài một cách tỉ mỉ theo đúng thứ tự các lớp giải phẫu ban đầu để đảm bảo quá trình lành thương đạt kết quả thẩm mỹ và chức năng tốt nhất."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "- Phẫu thuật chỉnh hình xương hai hàm: áp dụng trong các trường hợp nặng không thể điều trị bù trừ bằng nắn chỉnh răng đơn thuần."}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "+ Khâu đóng phần mềm theo các lớp giải phẫu."}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "- Vết thương nhỏ, không chảy máu, không dị vật: không phẫu thuật, điều trị kháng sinh, chống phù nề, thay băng, theo dõi."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "- Can thiệp phẫu thuật chỉnh hình xương: Trong các trường hợp kém phát triển xương hàm trên nặng không thể điều trị bù trừ bằng nắn chỉnh răng đơn thuần được thì phải kết hợp chỉnh hình xương hàm trên."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["16. SAI KHỚP CẮN LOẠI II DO XƯƠNG HAI HÀM.", "IV. ĐIỀU TRỊ", "2. Điều trị cụ thể", "2.2. Bệnh nhân đã qua thời kỳ tăng trưởng"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["56. GÃY XƯƠNG GÒ MÁ CUNG TIẾP", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1. Lâm sàng", "b. Điều trị phẫu thuật"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["53. CHẤN THƯƠNG PHẦN MỀM VÙNG HÀM MẶT", "IV. ĐIỀ U TRỊ", "2. Điều trị cụ thể", "2.4. Vết thương xuyên"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["22. SAI KHỚP CẮN LOẠI III DO KÉM PHÁT TRIỂN XƯƠNG HÀM TRÊN", "VI. ĐIỀU TRỊ", "b. Bệnh nhân hết thời kỳ tăng trưởng"]}]}
