{"question": "Quy trình sửa soạn hệ thống ống tủy trong điều trị viêm tủy răng sữa không hồi phục yêu cầu sử dụng trâm tay K-file số mấy làm kích thước khởi đầu?", "claim": "Khi sửa soạn hệ thống ống tủy cho răng sữa viêm tủy không hồi phục, bác sĩ cần bắt đầu bằng trâm tay K-file số 15 để tạo đường trượt an toàn.", "internal_evidence": [{"evidence_id": "I1", "content": "Khuyến cáo lâm sàng trong điều trị viêm tủy răng sữa không hồi phục:\n- Bác sĩ cần thực hiện mở tủy và làm sạch hệ thống ống tủy theo đúng quy chuẩn.\n- Bắt buộc sử dụng trâm tay K-file số 15 làm kích thước khởi đầu để thăm dò và tạo đường trượt an toàn."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "+ Sửa soạn hệ thống ống tủy."}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "+ Carbamazepine thường là lựa chọn đầu tiên khi điều trị đau thần kinh V, có thể thay thế bằng Oxcarbazepine hoặc gabapentin để giảm tác dụng phụ."}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "- Phẫu thuật chỉnh hình xương hàm dưới: áp dụng trong các trường hợp nặng không thể điều trị bù trừ bằng nắn chỉnh răng đơn thuần."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "+ Nước bọt: Dòng chảy và tốc độ chảy của nước bọt là yếu tố làm sạch tự nhiên để loại bỏ các mảnh vụn thức ăn còn sót lại. Tạo một lớp màng mỏng trên bề mặt của răng từ nước bọt có vai trò như một hàng rào bảo vệ men răng khỏi pH nguy cơ. Ngoài ra nước bọt còn có vai trò đệm làm giảm độ toan của môi trường quanh răng và có tác dụng đề kháng với sâu răng. Nước bọt còn là nguồn cung cấp các chất khoáng, hỗ trợ quá trình tái khoáng để có thể phục hồi các tổn thương sâu răng sớm."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["5. VIÊM TỦY RĂNG SỮA", "IV. ĐIỀU TRỊ", "2. Viêm tủy không hồi phục"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["48. ĐAU DÂY THẦN KINH V", "IV. ĐIỀU TRỊ", "2. Điều trị cụ thể", "2.2. Điều trị triệu chứng", "2.2.1 Nội khoa"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["15. SAI KHỚP CẮN LOẠI II DO KÉM PHÁT TRIỂN XƯƠNG HÀM DƯỚI", "IV. ĐIỀU TRỊ", "2. Điều trị cụ thể", "2.2. Bệnh nhân đã hết thời kỳ tăng trưởng"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["4. SÂU RĂNG SỮA", "II. NGUYÊN NHÂN"]}]}
