{"question": "Thuốc nào thường là lựa chọn đầu tiên trong điều trị nội khoa đau dây thần kinh V và có thể thay thế bằng thuốc nào để giảm tác dụng phụ?", "claim": "Carbamazepine thường là lựa chọn đầu tiên khi điều trị đau thần kinh V, và có thể dùng Oxcarbazepine hoặc gabapentin thay thế để giảm tác dụng phụ.", "internal_evidence": [{"evidence_id": "I1", "content": "Trong phác đồ điều trị nội khoa chứng đau dây thần kinh số V, bác sĩ thường chỉ định Carbamazepine làm thuốc đầu tay. Trường hợp cần hạn chế các tác dụng phụ không mong muốn, có thể chuyển sang sử dụng Oxcarbazepine hoặc gabapentin để thay thế hiệu quả."}], "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "- Sau khi răng nguyên nhân và các răng liên quan được điều trị nội nha, theo dõi mà tổn thương cuống không tiến triển tốt, tiến hành điều trị phẫu thuật lấy đi toàn bộ lớp vỏ nang có hoặc không có cắt phần cuống răng nguyên nhân."}, {"quote_id": "P2.Q1", "evidence_id": "P2", "text": "+ Carbamazepine thường là lựa chọn đầu tiên khi điều trị đau thần kinh V, có thể thay thế bằng Oxcarbazepine hoặc gabapentin để giảm tác dụng phụ."}, {"quote_id": "P3.Q1", "evidence_id": "P3", "text": "- Dùng nước súc miệng có tác dụng kìm khuẩn hoặc sát khuẩn cho những người không thể làm sạch mảng bám răng bằng các biện pháp cơ học như bị tật, đang phẫu thuật vùng miệng, hàm mặt, mang khí cụ nắn chỉnh răng."}, {"quote_id": "P4.Q1", "evidence_id": "P4", "text": "Đối với các thể bệnh đau (viêm quanh cuống cấp, áp xe quanh cuống cấp) phải điều trị bằng kháng sinh toàn thân, đặc biệt trong trường hợp áp xe quanh cuống cấp có viêm mô tế bào."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["12. VIÊM QUANH CUỐNG RĂNG", "IV. ĐIỀU TRỊ", "3. Điều trị cụ thể", "c. Điều trị phẫu thuật"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["48. ĐAU DÂY THẦN KINH V", "IV. ĐIỀU TRỊ", "2. Điều trị cụ thể", "2.2. Điều trị triệu chứng", "2.2.1 Nội khoa"]}, {"evidence_id": "P3", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["6. VIÊM LỢI LIÊN QUAN ĐẾN MẢNG BÁM RĂNG", "IV. ĐIỀU TRỊ"]}, {"evidence_id": "P4", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["12. VIÊM QUANH CUỐNG RĂNG", "IV. ĐIỀU TRỊ", "3. Điều trị cụ thể", "a. Điều trị toàn thân"]}]}
